SELECT merchant, last_txn_time, pct_7_eleven FROM (SELECT merchant, MAX(txn_time) AS last_txn_time, ROUND((100 * SUM(CASE WHEN merchant = '7-Eleven' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_7_eleven FROM transactions WHERE is_flagged GROUP BY merchant) AS x WHERE pct_7_eleven < 71 ORDER BY pct_7_eleven, last_txn_time;
